import sys
from collections import Counter

with open('/workdir/data/dict.txt') as f:
    words = [line.strip() for line in f if line.strip()]
valid_words = [w.lower() for w in words if all(c.isalpha() for c in w)]

# Create a set of valid words for quick lookup
valid_set = set(valid_words)

# Try a simple shift derangement: shift by 1
def shift_char(c, shift=1):
    if c.isalpha():
        base = ord('a')
        return chr((ord(c) - base + shift) % 26 + base)
    return c

# Check how many words map to valid words under shift by 1
shift1_valid = []
for w in valid_words:
    if len(w) >= 4:
        transformed = ''.join(shift_char(c, 1) for c in w)
        if transformed in valid_set:
            shift1_valid.append(w)
print(f'Shift 1: {len(shift1_valid)} words map to valid words')
""}

